//! The image area Heeler develops of a raw frame for the formats whose
//! files do not state it in LibRaw's terms (CR2, CR3, ARW, NEF, RW2, ORF):
//! LibRaw's own area for each camera and raw size, so documents made
//! before the Rust path keep their geometry (crops and strokes are stored
//! as fractions of the image), and its white level where the file does
//! not state one. The
//! table (geometry_table.rs) is generated by heeler-raw's
//! examples/geometry.rs from LibRaw's reading of the corpus.

/// One camera's area for one raw frame size.
#[derive(Clone, Copy, Debug)]
pub struct Geometry {
    pub make: &'static str,
    pub model: &'static str,
    /// The raw frame's width and height.
    pub raw: (u32, u32),
    pub top: u32,
    pub left: u32,
    pub width: u32,
    pub height: u32,
    /// The CFA colors at the area's top left: (0, 0), (0, 1), (1, 0),
    /// (1, 1); 0 red, 1 green, 2 blue.
    pub colors: [u8; 4],
    /// The white level, or 0 where the file states its own.
    pub white: u32,
}

/// A four-color camera's area for one raw frame size (a CMYG or RGBE
/// sensor), as LibRaw opens its files.
#[derive(Clone, Copy, Debug)]
pub struct FourGeometry {
    pub make: &'static str,
    pub model: &'static str,
    pub raw: (u32, u32),
    pub top: u32,
    pub left: u32,
    pub width: u32,
    pub height: u32,
    /// LibRaw's color index (0 to 3) at row (modulo 8) and column (modulo
    /// 2) of the area, row by row.
    pub pattern: [u8; 16],
    pub white: u32,
    /// The black level of each color.
    pub black: [u32; 4],
}

include!("geometry_table.rs");

/// The area for a camera's raw frame of `raw` size.
pub fn find(make: &str, model: &str, raw: (u32, u32)) -> Option<&'static Geometry> {
    GEOMETRY.iter().find(|g| g.make == make && g.model == model && g.raw == raw)
}

/// The area LibRaw develops of a camera's DNG of `raw` size that states
/// no image area of its own (Pentax, Samsung and Ricoh bodies, Leica's
/// SL2): LibRaw's table for the camera.
pub fn find_dng(make: &str, model: &str, raw: (u32, u32)) -> Option<&'static Geometry> {
    DNG_GEOMETRY.iter().find(|g| g.make == make && g.model == model && g.raw == raw)
}

/// The area and white level LibRaw develops of a camera's image of three
/// samples a pixel (a Canon sRAW or mRAW, a Sony M or S size) of `raw`
/// size.
pub fn find_rgb(make: &str, model: &str, raw: (u32, u32)) -> Option<&'static Geometry> {
    RGB_GEOMETRY.iter().find(|g| g.make == make && g.model == model && g.raw == raw)
}

/// A NEF or RAF camera's white level for samples of `depth` bits (LibRaw's).
pub fn nef_white(make: &str, model: &str, depth: u32) -> Option<u32> {
    NEF_WHITE.iter().find(|w| w.0 == make && w.1 == model && w.2 == depth).map(|w| w.3)
}

/// An ORF, NEF or RW2 camera's black level as LibRaw takes it where the
/// file states none: red, the green on red's row, the other green, blue.
pub fn black(make: &str, model: &str) -> Option<[u32; 4]> {
    BLACK.iter().find(|b| b.0 == make && b.1 == model).map(|b| b.2)
}

/// A four-color camera's area for its raw frame of `raw` size.
pub fn find_four(make: &str, model: &str, raw: (u32, u32)) -> Option<&'static FourGeometry> {
    FOUR_GEOMETRY.iter().find(|g| g.make == make && g.model == model && g.raw == raw)
}

/// A four-color camera's rows, whatever their frame size (for a file
/// that does not state its frame's size).
pub fn four_rows<'a>(make: &'a str, model: &'a str) -> impl Iterator<Item = &'static FourGeometry> + 'a {
    FOUR_GEOMETRY.iter().filter(move |g| g.make == make && g.model == model)
}
